using System.Text.Json;
using DoomSharp.Core;
using DoomSharp.Data;
using DoomSharp.Rendering;
using Xunit;

namespace DoomSharp.Tests.Unit;

/// <summary>Vector records from tools/charact/rmain_vectors.json.</summary>
public static class RMainVectors
{
    public static JsonElement PointOnSide { get; } = Load("pointOnSide");
    public static JsonElement PointToAngle2 { get; } = Load("pointToAngle2");
    public static JsonElement ScaleFromGlobalAngle { get; } = Load("scaleFromGlobalAngle");
    public static JsonElement DrawColumn { get; } = Load("drawColumn");
    public static JsonElement DrawFuzzColumn { get; } = Load("drawFuzzColumn");
    public static JsonElement DrawSpan { get; } = Load("drawSpan");
    public static JsonElement DrawPatch { get; } = Load("drawPatch");

    private static JsonDocument? _doc;

    private static JsonElement Load(string section)
    {
        if (_doc == null)
        {
            var json = File.ReadAllText(
                Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "..", "..",
                    "tools", "charact", "rmain_vectors.json"));
            _doc = JsonDocument.Parse(json);
        }

        return _doc.RootElement.GetProperty(section).Clone();
    }
}

[Collection("RendererSerial")]
public class RendererMathTests
{
    [Fact]
    public void PointOnSide_MatchesCVectors()
    {
        foreach (var v in RMainVectors.PointOnSide.EnumerateArray())
        {
            var node = new Node
            {
                X = v.GetProperty("nx").GetInt32(),
                Y = v.GetProperty("ny").GetInt32(),
                Dx = v.GetProperty("ndx").GetInt32(),
                Dy = v.GetProperty("ndy").GetInt32(),
            };

            var side = RendererMath.PointOnSide(v.GetProperty("x").GetInt32(), v.GetProperty("y").GetInt32(), node);

            Assert.Equal(v.GetProperty("side").GetInt32(), side);
        }
    }

    [Fact]
    public void PointToAngle2_MatchesCVectors()
    {
        foreach (var v in RMainVectors.PointToAngle2.EnumerateArray())
        {
            var angle = RendererMath.PointToAngle2(
                v.GetProperty("x1").GetInt32(),
                v.GetProperty("y1").GetInt32(),
                v.GetProperty("x2").GetInt32(),
                v.GetProperty("y2").GetInt32());

            Assert.Equal((uint)v.GetProperty("angle").GetUInt32(), angle);
        }
    }

    [Fact]
    public void PointToDist_MatchesCVectors()
    {
        foreach (var v in RMainVectors.PointToAngle2.EnumerateArray())
        {
            var expected = v.GetProperty("dist").GetInt32();
            if (expected == -1)
            {
                // C harness skipped the degenerate dx==dy==0 case (UB).
                continue;
            }

            RendererMath.ViewX = v.GetProperty("x1").GetInt32();
            RendererMath.ViewY = v.GetProperty("y1").GetInt32();
            var dist = RendererMath.PointToDist(
                v.GetProperty("x2").GetInt32(),
                v.GetProperty("y2").GetInt32());

            Assert.Equal(expected, dist);
        }
    }

    [Fact]
    public void ScaleFromGlobalAngle_MatchesCVectors()
    {
        foreach (var v in RMainVectors.ScaleFromGlobalAngle.EnumerateArray())
        {
            if (v.TryGetProperty("fatal", out _))
            {
                // C hit FixedDiv overflow (I_Error); C# FixedDiv throws
                // DoomFatalException with the same sentinel semantics.
                RendererMath.ViewAngle = v.GetProperty("viewangle").GetUInt32();
                RendererMath.RwNormalAngle = (int)v.GetProperty("rw_normalangle").GetUInt32();
                RendererMath.RwDistance = v.GetProperty("rw_distance").GetInt32();
                RendererMath.DetailShift = v.GetProperty("detailshift").GetInt32();
                RendererMath.Projection = 160 << 16;
                Assert.Throws<DoomFatalException>(() =>
                    RendererMath.ScaleFromGlobalAngle(v.GetProperty("visangle").GetUInt32()));
                continue;
            }

            RendererMath.ViewAngle = v.GetProperty("viewangle").GetUInt32();
            RendererMath.RwNormalAngle = (int)v.GetProperty("rw_normalangle").GetUInt32();
            RendererMath.RwDistance = v.GetProperty("rw_distance").GetInt32();
            RendererMath.DetailShift = v.GetProperty("detailshift").GetInt32();
            RendererMath.Projection = 160 << 16;

            var scale = RendererMath.ScaleFromGlobalAngle(v.GetProperty("visangle").GetUInt32());

            Assert.Equal(v.GetProperty("scale").GetInt32(), scale);
        }
    }
}
